def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    vals = [x for row in grid for x in row]
    bg = Counter(vals).most_common(1)[0][0]
    choices = []
    # Opposing boundary bars of the same color and length.
    for axis in (0, 1):
        n = w if axis == 0 else h  # coordinate along each bar
        edge_a = grid[0][:] if axis == 0 else [grid[r][0] for r in range(h)]
        edge_b = grid[-1][:] if axis == 0 else [grid[r][-1] for r in range(h)]
        for color in set(edge_a + edge_b) - {bg}:
            for a in _runs(edge_a, bg):
                if a[2] != color:
                    continue
                for b in _runs(edge_b, bg):
                    if b[2] == color and b[1] - b[0] == a[1] - a[0]:
                        choices.append((a[1] - a[0], axis, color, a, b))
    if not choices:
        return out
    _, axis, rail, a, b = max(choices, key=lambda x: x[0])
    depth = h if axis == 0 else w

    def get(pos, d):
        return grid[d][pos] if axis == 0 else grid[pos][d]

    def put(pos, d, value):
        if axis == 0:
            out[d][pos] = value
        else:
            out[pos][d] = value

    markers = []
    for side, run in ((0, a), (1, b)):
        for pos in range(run[0], run[1]):
            for d in range(1, depth - 1):
                color = get(pos, d)
                if color != bg and color != rail:
                    markers.append((side, pos, d, color))

    # A clue shoots toward its own boundary. Its aligned counterpart paints
    # a full stripe from the opposite boundary, preserving the rail cells.
    for side, pos, d, color in markers:
        if side == 0:
            for q in range(1, d):
                put(pos, q, color)
            other_pos = b[0] + pos - a[0]
        else:
            for q in range(d + 1, depth - 1):
                put(pos, q, color)
            other_pos = a[0] + pos - b[0]
        for q in range(depth):
            if get(other_pos, q) != rail:
                put(other_pos, q, color)
    for side, pos, d, color in markers:
        put(pos, d, 4)
    return out


